WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pc_c_formula'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '组合数求解', 'kp-pc-c-formula', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "组合数常用公式"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "C(n, m) = C(n, n-m)。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、实战秒杀"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果题目让你算 C(10, 8)，千万别去列一大串乘法。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "因为从 10 个人里挑 8 个人去开会，等价于从 10 个人里挑出 2 个人【留下来】！"}]}, {"type": "katexBlock", "attrs": {"content": "C_{10}^8 = C_{10}^2 = \\frac{10 \\times 9}{2 \\times 1} = 45"}}]}$$ AS jsonb), NULL, '组合数求解的核心考点与实战推导。', category_node.id, CAST('["数量关系", "排列组合", "组合数求解"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pc_c_formula", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
